  function downloadsPage() { const cards = downloads.map(([title, text, category, href]) => `<a class="document-download" href="${href}" target="_blank" rel="noreferrer"><span>${category}</span><strong>${title}</strong><p>${text}</p><b>PDF öffnen <i>→</i></b></a>`).join(""); return `${hero("green", "Downloads", "Alles Wichtige<br>auf einen Blick.", "Formulare und ausführliche Regelwerke finden Sie gesammelt an einer Stelle. Die wichtigsten Informationen erklären wir direkt auf der Website.", button("Mitglied werden", "#/mitglied-werden", "cream"))}<section class="section downloads-page"><div class="downloads-web-content"><div><p class="kicker">Direkt auf der Website</p><h2>Wissen, statt<br><em>suchen.</em></h2></div><div><a href="#/mitglied-werden"><strong>Mitglied werden</strong><span>Antrag, Beiträge, Gebühren und Kündigung</span><b>→</b></a><a href="#/gruppen"><strong>Unsere Gruppen</strong><span>Alter, Training, Kontakt und Überblick</span><b>→</b></a><a href="#/termine"><strong>Termine &amp; Aktuelles</strong><span>Höhepunkte und Vereinsleben</span><b>→</b></a><a href="#/satzung"><strong>Vereinssatzung</strong><span>Rechtliche Grundlage des Vereins</span><b>→</b></a></div></div><div class="section-heading downloads-heading"><div><p class="kicker">Dokumente zum Öffnen</p><h2 class="section-title">Formulare &amp;<br><em>Unterlagen.</em></h2></div><p>Diese Dokumente werden nur dann benötigt, wenn die jeweilige Situation es erfordert. Sie öffnen sich nach einem Klick als offizielles PDF.</p></div><div class="document-download-grid">${cards}</div></section>`; }
  function organization() { return `${hero("green", "Organisation", "Gemeinsam<br>Verantwortung tragen.", "Vorstand, Präsidium, Komitee und Gesamtverein greifen bei den Lachatrappern ineinander – damit Training, Brauchtum und Veranstaltungen funktionieren.", button("Vereinsinfos ansehen", "#/verein", "cream"))}<section class="section organisation-page"><div class="section-heading"><div><p class="kicker">Gremienstruktur</p><h2 class="section-title">So sind die <em>Lachatrapper</em><br>aufgestellt.</h2></div></div>${governanceChart()}</section><section class="cta-band"><div><p class="kicker">Zusammen für die Fasnet</p><h2>Viele Aufgaben.<br>Ein Verein.</h2></div><div><p>Ob auf der Bühne, beim Training, im Hintergrund oder in der Organisation: Jede Aufgabe trägt die Fasnet in Dornstadt mit.</p>${button("Unsere Gruppen entdecken", "#/gruppen")}</div></section>`; }
  const membershipApplicationUrl = "https://easyverein.com/public/KGL1972/applicationform/24168";
  function membershipApplication() { return `${hero("red", "Mitglied werden", "Werde Teil<br>der Fasnet.", "Dein Mitgliedsantrag läuft sicher und direkt über den offiziellen Mitgliederbereich von EasyVerein.", `<a class="button cream" href="${membershipApplicationUrl}" target="_blank" rel="noreferrer">Zum Mitgliedsantrag <span>→</span></a>`)}<section class="section membership-fees"><div class="section-heading"><div><p class="kicker">Gebührenordnung</p><h2 class="section-title">Beiträge &amp;<br><em>Gebühren.</em></h2></div><p>Die Übersicht entspricht den aktuell im offiziellen Mitgliedsantrag veröffentlichten Angaben. Maßgeblich bleibt immer der Antrag selbst.</p></div><div class="member-fee-cards"><article class="member-fee-card"><h3>Aktive</h3><dl><div><dt>0–17 Jahre</dt><dd>40 € / Jahr</dd></div><div><dt>ab 18 Jahre</dt><dd>110 € / Jahr</dd></div></dl></article><article class="member-fee-card"><h3>Passive</h3><dl><div><dt>0–17 Jahre</dt><dd>10 € / Jahr</dd></div><div><dt>ab 18 Jahre</dt><dd>30 € / Jahr</dd></div></dl></article><article class="member-fee-card"><h3>Familienrabatt</h3><dl><div><dt>1–2 Erwachsene + 1 Kind</dt><dd>10 %</dd></div><div><dt>2 Kinder</dt><dd>20 %</dd></div><div><dt>ab 3 Kinder</dt><dd>30 %</dd></div></dl></article><article class="member-fee-card"><h3>Sportabteilung</h3><dl><div><dt>Zusätzlicher Abteilungsbeitrag</dt><dd>40 € / Jahr</dd></div><div><dt>Einmalige Kaution</dt><dd>50 €</dd></div></dl></article></div><div class="membership-details"><article class="membership-extras"><p class="kicker">Für Aktive</p><h3>Kostüme, Häs &amp; Ausfahrten.</h3><dl><div><dt>Häsmiete Maskengruppe &amp; Elferrat</dt><dd>15 € bis 17 Jahre · 25 € ab 18 Jahren</dd></div><div><dt>Gardekostüm</dt><dd>50 €</dd></div><div><dt>Busfahrten</dt><dd>Für aktive Mitglieder im Jahresbeitrag enthalten. Bei Bedarf kann per Komiteebeschluss ein zusätzliches Busgeld bis höchstens 50 € pro Person und Geschäftsjahr erhoben werden.</dd></div><div><dt>Passive Mitglieder</dt><dd>5 € Busgeld pro Ausfahrt – bei verfügbarer Platzkapazität.</dd></div></dl></article><aside class="membership-termination"><p class="kicker">Mitgliedschaft beenden</p><h3>Kündigung an den<br><em>Schatzmeister.</em></h3><p>Kündigungen werden ausschließlich per E-Mail an den Schatzmeister entgegengenommen.</p><a href="mailto:schatzmeister@lachatrapper.de?subject=K%C3%BCndigung%20Mitgliedschaft">schatzmeister@lachatrapper.de <b>→</b></a><small>Hilfreich für die Zuordnung: vollständiger Name und – falls nötig – Geburtsdatum.</small></aside></div></section><section class="section alt membership-application"><div class="section-heading"><div><p class="kicker">Dein Einstieg</p><h2 class="section-title">Ein Antrag.<br>Viele Möglichkeiten.</h2></div><p>Aktiv auf der Bühne, im Brauchtum, hinter den Kulissen oder als förderndes Mitglied: Im Antrag können bis zu vier Gruppen ausgewählt werden.</p></div><div class="uploads"><div><strong>Mitgliedsantrag online ausfüllen</strong><p>Der Antrag wird auf der offiziellen EasyVerein-Seite geöffnet. Dort werden deine Angaben direkt verarbeitet, die E-Mail-Adresse bestätigt und die SEPA-Angaben hinterlegt.</p></div><a class="button" href="${membershipApplicationUrl}" target="_blank" rel="noreferrer">Antrag öffnen <span>→</span></a></div></section>`; }
